/* Velo V4 preservation layer. Browser demonstration, no native video or device APIs. */
const PC=window.PLAYER_CONFIG;
window.VELO_PLAYER_V4=true;
const playerLegacy={player,doAction,openModal,closeModal,renderModal,scheduleHud,showHud,nav,back,render};
paths.rotate='M20 8V3h-5 M20 3l-5 5 M4 16v5h5 M4 21l5-5 M8 4H5v8 M16 20h3v-8';
paths.camera='M3 6h5l2-3h4l2 3h5v15H3z M12 9a4 4 0 100 8 4 4 0 000-8';
paths.pip='M3 4h18v16H3z M12 11h7v7h-7z';
const PV={kind:'drawer',stack:[],rootFocus:null,anchor:null,gesture:null,inputMode:'mouse',orientation:'auto',feedbackTimer:null,tapTimer:null,hideTimer:null,lastTap:null,lastDouble:0,repeat:{side:'',at:0,seconds:0},temporaryBase:null,preview:null,trackCase:'available',episodeCase:'available',screenshotCase:'available',pipCase:'available',pip:false,switchOutcome:'success',pendingChoice:null,selectionToken:0,tabScroll:{},channel:PC.defaultChannel,gain:PC.defaultGain,audioDelay:PC.defaultAudioDelay,zoom:PC.defaultZoom,sleep:PC.defaultSleep,subtitleSize:PC.defaultSubtitleSize,subtitlePosition:PC.defaultSubtitlePosition,sameScreen:PC.defaultSameScreen,screenshotSaved:false};
const pCanControl=()=>!(state.room.joined&&state.room.role==='guest'&&state.room.control==='hostOnly');
const pClamp=(v,min=0,max=100)=>Math.max(min,Math.min(max,v));
const pTime=()=>state.player.time*PC.durationSeconds/100;
function pTimeLabel(seconds){let s=Math.round(pClamp(seconds,0,PC.durationSeconds));return [Math.floor(s/3600),Math.floor(s/60)%60,s%60].map(n=>String(n).padStart(2,'0')).join(':')}
function pButton(label,action,ic,extra='',disabled=false){return `<button class="p-control ${extra}" data-action="${action}" aria-label="${label}" title="${label}${disabled?' · 仅房主可控制':''}" ${disabled?'disabled':''}>${icon(ic)}</button>`}
function pChip(label,action,disabled=false){return `<button class="p-chip" data-action="${action}" ${disabled?'disabled aria-description="仅房主可控制"':''}>${label}</button>`}
function pHeat(at){return Math.min(1,.09+PC.heatPeaks.reduce((v,p)=>v+p.height*Math.exp(-Math.pow((at-p.at)/p.width,2)),0))}
function pHeatSvg(){let path=Array.from({length:PC.heatBuckets+1},(_,i)=>`${i?'L':'M'}${i/PC.heatBuckets*1000},${40-pHeat(i/PC.heatBuckets)*34}`).join(' ');return `<svg viewBox="0 0 1000 40" preserveAspectRatio="none" aria-hidden="true"><path d="${path} L1000,40 L0,40 Z"/></svg>`}
function pNearestPeak(seconds){let n=Math.round(seconds/PC.durationSeconds*PC.heatBuckets),best=n;for(let i=Math.max(0,n-PC.heatSnapBuckets);i<=Math.min(PC.heatBuckets,n+PC.heatSnapBuckets);i++)if(pHeat(i/PC.heatBuckets)>pHeat(best/PC.heatBuckets))best=i;return best/PC.heatBuckets*PC.durationSeconds}
function pSetPosition(seconds){const wasEnded=state.scenario==='empty';state.player.time=pClamp(seconds,0,PC.durationSeconds)/PC.durationSeconds*100;if(state.player.time>=100){state.player.playing=false;state.scenario='empty';state.player.hud=true;PV.preview=null;render();return}if(wasEnded){state.scenario='normal';state.player.hud=true;render();return}pSync()}
function pCommitSeek(seconds,{assist=false}={}){if(!pCanControl()||state.player.locked)return pFeedback('仅房主可调整进度','center','lock');let target=pClamp(seconds,0,PC.durationSeconds),snapped=assist&&state.settings.heatmap&&pHeat(target/PC.durationSeconds)>PC.heatThreshold;if(snapped)target=pNearestPeak(target);PV.preview=null;pSetPosition(target);pFeedback((snapped?'热点辅助 · ':'已定位 · ')+pTimeLabel(target),'center','clock');scheduleHud()}
function pSeek(delta){if(!pCanControl()||state.player.locked)return pFeedback('仅房主可调整进度','center','lock');let target=pClamp(pTime()+delta,0,PC.durationSeconds);pSetPosition(target);const side=delta<0?'left':'right',now=Date.now();PV.repeat.seconds=PV.repeat.side===side&&now-PV.repeat.at<PC.repeatSeekMs?PV.repeat.seconds+Math.abs(delta):Math.abs(delta);PV.repeat.side=side;PV.repeat.at=now;pSync();pFeedback((delta<0?'−':'+')+PV.repeat.seconds+' 秒',side,delta<0?'rewind':'forward');scheduleHud()}
function pFeedback(text,where='center',ic='info',persistent=false){clearTimeout(PV.feedbackTimer);let node=$('#p-feedback');if(!node)return;node.dataset.position=where;node.innerHTML=icon(ic)+`<span>${esc(text)}</span>`;node.classList.add('visible');if(!persistent)PV.feedbackTimer=setTimeout(()=>node.classList.remove('visible'),PC.feedbackMs)}
function pFeedbackLevel(kind,value){let node=$('#p-level-feedback');if(!node)return;node.dataset.side=kind==='brightness'?'left':'right';node.innerHTML=icon(kind==='brightness'?'sun':'volume')+`<div class="p-level-bar"><i style="height:${value}%"></i></div><strong>${Math.round(value)}%</strong><span>${kind==='brightness'?'亮度':'音量'} · 演示</span>`;node.classList.add('visible')}
function pHideLevel(){setTimeout(()=>$('#p-level-feedback')?.classList.remove('visible'),PC.feedbackMs)}
function pSubtitle(){if(!state.settings.subtitle||PV.trackCase==='empty')return '';let chinese='我们总会在某个地方，再次相遇。',english='Somewhere, our paths will cross again.',tracks=[state.player.subtitle,state.player.secondary].filter((v,i,a)=>v&&v!=='关闭'&&a.indexOf(v)===i);if(!tracks.length)return '';let text=v=>v.startsWith('English')?english:chinese;return `<div class="p-subtitle" style="font-size:${PV.subtitleSize}px;bottom:${PV.subtitlePosition}%;color:${state.subtitleColor==='淡黄'?'#f4df95':state.subtitleColor==='纯白'?'#fff':'#faf3df'}">${text(tracks[0])}${tracks[1]?`<small>${text(tracks[1])}</small>`:''}</div>`}
function pStatus(){if(state.scenario==='normal')return '';let loading=state.scenario==='loading',ended=state.scenario==='empty';return `<div class="p-status"><div>${loading?'<span class="spinner"></span>':icon(ended?'check':'warning')}<h2>${loading?'正在缓冲':ended?'播放已结束':state.scenario==='denied'?'当前影片不可访问':'暂时无法播放'}</h2><p>${loading?'等待媒体准备 · 演示':ended?'故事告一段落，下一段旅程在等你。':'连接中断或播放源不可用，已保留当前位置。'}</p><div class="flex wrap" style="justify-content:center">${pCanControl()?btn(ended?'重新播放':loading?'结束缓冲演示':'重试','p:recover','primary'):btn('申请房主恢复播放','p:request','outline')}${!loading&&!ended?btn('选择版本','p:open:versions','outline'):''}</div></div></div>`}
player=function(){let m=selectedMedia(),series=m.duration.includes('集'),restricted=!pCanControl();document.body.classList.toggle('player-landscape-preview',PV.orientation==='landscape');document.documentElement.style.setProperty('--prototypebar-height',($('#prototype-bar')?.offsetHeight||42)+'px');let time=PV.preview??pTime();return `<div class="player-shell p-v4 ${state.player.hud?'':'p-hud-hidden'} ${state.player.locked?'p-locked':''}" id="player-stage" data-orientation="${PV.orientation}"><div class="player-scene p-scene" style="filter:brightness(${.3+state.player.brightness*.007});transform:scale(${PV.zoom/100})">${ART(m.art,true)}</div><div class="p-vignette"></div><div class="p-top p-hud" ${state.player.locked?'inert':''}><div class="p-title-side">${pButton('返回影片','back','back')}<div class="p-title"><strong>${m.title}${series?' · 第 '+state.season+' 季 第 '+state.episode+' 集':''}</strong><small>${restricted?'访客 · 仅房主可控制':state.service+' · '+state.player.core+' · 播放画面为演示'}</small></div></div><div class="p-top-tools">${pButton(state.settings.danmaku?'关闭弹幕':'开启弹幕','p:danmaku','subtitle',state.settings.danmaku?'is-on':'')}${pButton('投屏 · DLNA','p:open:cast','cast')}${pButton('横竖屏布局演示','p:orientation','rotate')}${pButton('更多播放设置','p:drawer:video','more')}</div></div><div class="p-left-edge">${pButton(state.player.locked?'解锁控件':'锁定控件','p:lock',state.player.locked?'lock':'unlock','p-lock')}</div><div class="p-right-edge p-hud" ${state.player.locked?'inert':''}>${pButton('截图 · 演示','p:screenshot','camera')}${pButton('画中画 · 演示','p:pip','pip')}</div>${state.settings.danmaku?`<div class="p-danmaku" style="opacity:${(state.danmakuOpacity||70)/100};font-size:${state.danmakuSize||20}px"><span>这一刻好安静</span><span>像走进了一幅画</span></div>`:''}${pSubtitle()}<div class="p-context-actions p-hud" ${state.player.locked?'inert':''}><button class="p-chip p-skip-intro" id="p-skip-intro" data-action="p:skip-intro" ${PC.introEndPercent>0&&state.player.time<PC.introEndPercent?'':'hidden'} ${restricted?'disabled aria-description="仅房主可跳过片头"':''}>跳过片头 ${icon('skip')}</button></div><div id="p-feedback" class="p-feedback" aria-live="polite"></div><div id="p-level-feedback" class="p-level-feedback" aria-live="polite"></div><div class="p-bottom p-hud" ${state.player.locked?'inert':''}><div class="p-timeline-wrap"><div class="p-seek-preview" id="p-seek-preview"><div class="p-preview-image">${ART(m.art,true)}</div><span id="p-preview-time">${pTimeLabel(time)}</span><small id="p-preview-count">此刻 ${Math.round(pHeat(time/PC.durationSeconds)*PC.heatMaxCount)} 条弹幕</small><em id="p-preview-mode">精准预览</em></div><div class="p-timeline ${state.settings.heatmap?'has-heat':''}" id="p-timeline" role="slider" tabindex="${restricted||state.player.locked?'-1':'0'}" aria-label="播放进度，左右键每次 5 秒，Enter 热点辅助" aria-valuemin="0" aria-valuemax="${PC.durationSeconds}" aria-valuenow="${Math.round(time)}" aria-valuetext="${pTimeLabel(time)}" aria-disabled="${restricted||state.player.locked}">${state.settings.heatmap?`<div class="p-heat">${pHeatSvg()}</div>`:''}<div class="p-track"><i class="p-buffer" style="width:${Math.max(PC.bufferedPercent,state.player.time)}%"></i><i class="p-skip-zone intro" style="width:${PC.introEndPercent}%"></i><i class="p-skip-zone outro" style="left:${PC.outroStartPercent}%;width:${100-PC.outroStartPercent}%"></i><i class="p-played" style="width:${time/PC.durationSeconds*100}%"></i><i class="p-playhead" style="left:${time/PC.durationSeconds*100}%"></i></div></div><div class="p-times"><span id="p-current-time">${pTimeLabel(time)}</span><span class="p-timeline-hint">${restricted?'仅房主可调整 · 可申请控制':state.settings.heatmap?'热力可预览 · 拖动精准定位':'拖动精准定位'}</span><span>${pTimeLabel(PC.durationSeconds)}</span></div></div><div class="p-control-row">${pButton(state.player.playing?'暂停':'播放','p:play',state.player.playing?'pause':'play','',restricted)}${pButton(series?'下一集':'下一个影片','p:next','skip','',restricted)}<span class="p-bottom-spacer"></span>${pChip(state.player.speed+'×','p:popover:speed',restricted)}${pChip('字幕 · '+(PV.trackCase==='empty'?'无':!state.settings.subtitle||(state.player.subtitle==='关闭'&&state.player.secondary==='关闭')?'关':(state.player.subtitle==='关闭'?state.player.secondary:state.player.subtitle).startsWith('English')?'英':'简中'),'p:popover:subtitle-menu')}${pChip(series?'第 '+state.episode+' 集':'章节','p:popover:episode-menu',restricted)}${pChip('弹幕','p:drawer:danmaku')}</div>${restricted?`<button class="p-request" data-action="p:request">申请播放控制</button>`:''}</div>${state.player.locked?'<div class="p-lock-hint">控件已锁定 · 点左侧锁图标解锁</div>':''}${PV.pip?`<div class="p-pip-window"><div class="p-pip-art">${ART(m.art,true)}</div><span>画中画演示</span>${pButton('返回主画面','p:pip-close','close')}<small>${m.title} · ${state.player.playing?'播放中':'已暂停'}</small></div>`:''}${pStatus()}</div>`};
function pSync(){if(state.route!=='player')return;let skip=$('#p-skip-intro');if(skip)skip.hidden=!(PC.introEndPercent>0&&state.player.time<PC.introEndPercent);let shell=$('#player-stage');if(!shell)return;let seconds=PV.preview??pTime(),pct=seconds/PC.durationSeconds*100;$('.p-played')?.style.setProperty('width',pct+'%');$('.p-playhead')?.style.setProperty('left',pct+'%');$('#p-current-time')&&( $('#p-current-time').textContent=pTimeLabel(seconds));$('#p-timeline')?.setAttribute('aria-valuenow',String(Math.round(seconds)));$('#p-timeline')?.setAttribute('aria-valuetext',pTimeLabel(seconds));$('.p-scene')?.style.setProperty('filter',`brightness(${.3+state.player.brightness*.007})`);let speed=$('[data-action="p:popover:speed"]');if(speed)speed.textContent=state.player.speed+'×'}
function pPreview(seconds,mode='精准预览'){PV.hoverTime=pClamp(seconds,0,PC.durationSeconds);if(mode.includes('拖动'))PV.preview=PV.hoverTime;let node=$('#p-seek-preview'),line=$('#p-timeline');if(!node||!line)return;node.classList.add('visible');node.style.left=pClamp(PV.hoverTime/PC.durationSeconds*line.clientWidth,75,Math.max(75,line.clientWidth-75))+'px';$('#p-preview-time').textContent=pTimeLabel(PV.hoverTime);$('#p-preview-count').textContent=state.settings.heatmap?'此刻 '+Math.round(pHeat(PV.hoverTime/PC.durationSeconds)*PC.heatMaxCount)+' 条弹幕':'热力图已关闭';$('#p-preview-mode').textContent=mode}
function pClearPreview(){PV.preview=null;PV.hoverTime=null;$('#p-seek-preview')?.classList.remove('visible');pSync()}
function pCancelGesture(){let g=PV.gesture;if(g){clearTimeout(g.timer);if(g.intent==='vertical'){state.player[g.channel]=g.initialLevel;pSync()}}PV.gesture=null;if(PV.temporaryBase!==null){state.player.speed=PV.temporaryBase;PV.temporaryBase=null;pSync()}clearTimeout(PV.tapTimer);PV.lastTap=null;$('#p-feedback')?.classList.remove('visible');pClearPreview();pHideLevel()}
function pDispose(){pCancelGesture();clearTimeout(PV.hideTimer);clearTimeout(PV.feedbackTimer);PV.selectionToken++;PV.stack=[];PV.rootFocus=null;document.body.classList.remove('player-landscape-preview')}
nav=function(route){if(state.route==='player'&&route!=='player')pDispose();return playerLegacy.nav(route)};
back=function(){if(state.route==='player')pDispose();return playerLegacy.back()};
scheduleHud=function(){if(state.route!=='player')return playerLegacy.scheduleHud();clearTimeout(PV.hideTimer);if(!state.player.playing||state.scenario!=='normal'||state.modal||PV.gesture||state.player.locked)return;PV.hideTimer=setTimeout(()=>{if(state.modal||PV.gesture||!state.player.playing||state.scenario!=='normal')return;if(state.view==='tv'&&$('#player-stage')?.contains(document.activeElement))return;pSetHud(false)},PV.inputMode==='mouse'?PC.mouseHudMs:PC.touchHudMs)};
function pSetHud(show){if(state.player.locked)return;state.player.hud=show;$('#player-stage')?.classList.toggle('p-hud-hidden',!show);$$('.p-hud').forEach(n=>n.inert=!show);if(!show&&$('#player-stage')?.contains(document.activeElement))document.activeElement.blur();if(show)scheduleHud()}
showHud=function(){if(state.route!=='player')return playerLegacy.showHud();pSetHud(true)};
function pOpen(name,kind='drawer',anchor=null,{root=false}={}){if(state.player.locked)return;pCancelGesture();clearTimeout(PV.hideTimer);showHud();clearTimeout(PV.hideTimer);if(!state.modal||root){PV.stack=[];PV.rootFocus=captureFocus();PV.anchor=anchor||document.activeElement}else if(name!==state.modal){let found=PV.stack.findIndex(x=>x.name===name);if(found>=0){let old=PV.stack[found];PV.stack=PV.stack.slice(0,found);kind=old.kind}else PV.stack.push({name:state.modal,kind:PV.kind,tab:state.player.tab,scroll:$('.p-layer-scroll')?.scrollTop||0,focus:captureFocus()})}state.modal=name;PV.kind=kind;pRenderLayer()}
openModal=function(name){if(state.route!=='player')return playerLegacy.openModal(name);return pOpen(name,'drawer')};
closeModal=function(restore=true){if(state.route!=='player')return playerLegacy.closeModal(restore);PV.selectionToken++;if(PV.stack.length){let prev=PV.stack.pop();state.modal=prev.name;PV.kind=prev.kind;state.player.tab=prev.tab;pRenderLayer();requestAnimationFrame(()=>{if($('.p-layer-scroll'))$('.p-layer-scroll').scrollTop=prev.scroll;restoreFocus(prev.focus)});return}state.modal=null;$('#modal-root').innerHTML='';if(restore)restoreFocus(PV.rootFocus);PV.rootFocus=null;PV.anchor=null;scheduleHud()};
renderModal=function(){if(state.route!=='player')return playerLegacy.renderModal();pRenderLayer()};
function pRange(label,key,value,min,max,unit='',step=1){return `<div class="p-range-row"><div class="range-label"><label for="p-range-${key}">${label}</label><output id="p-out-${key}">${value}${unit}</output></div><input id="p-range-${key}" type="range" min="${min}" max="${max}" step="${step}" value="${value}" data-p-range="${key}" data-unit="${unit}"></div>`}
function pChoice(label,sub,action,selected=false,disabled=false){return `<button class="choice ${selected?'selected':''}" data-action="${action}" ${disabled?'disabled':''}><span class="choice-label">${label}${sub?`<p>${sub}</p>`:''}</span>${icon(selected?'check':'arrow')}</button>`}
function pLayerData(name){let m=selectedMedia(),series=m.duration.includes('集');if(name==='player-settings'){let t=state.player.tab,body=`<div class="p-drawer-tabs">${[['video','视频'],['audio','音频'],['subtitles','字幕'],['danmaku','弹幕']].map(([v,l])=>`<button class="${t===v?'active':''}" data-action="p:tab:${v}">${l}</button>`).join('')}</div><div class="p-tab-content">`;
if(t==='video')body+=row('画质与版本','只模拟选择与结果',state.player.quality,'p:open:versions')+row('画面比例','',state.player.ratio,'p:open:ratio')+row('播放核心','保留现有核心',state.player.core,'p:open:core')+toggle('自动跳过片头片尾','skipIntro')+toggle('自动播放下一集','autoplay')+pRange('画面缩放','zoom',PV.zoom,75,150,'%')+row('睡眠定时','仅保存本次演示选择',PV.sleep,'p:open:sleep')+row('亮度与音量','无手势的可点击替代','','p:open:levels')+row('播放队列','保留后续播放内容','','p:open:queue');
if(t==='audio')body+=row('音轨',PV.trackCase==='empty'?'没有可用轨道':'当前选择',PV.trackCase==='empty'?'不可用':state.player.audio,'p:open:audio')+pRange('音画同步','audioDelay',PV.audioDelay,-10,10,' 秒',.1)+pRange('音量增益','gain',PV.gain,-12,12,' dB')+row('声道','',PV.channel,'p:open:channel')+pRange('音量','volume',state.player.volume,0,100,'%')+btn('重置音频调整','p:reset-audio','outline small','refresh');
if(t==='subtitles')body+=toggle('显示字幕','subtitle')+row('主字幕','',PV.trackCase==='empty'?'无可用字幕':state.player.subtitle,'p:open:subtitle-language')+row('副字幕','与主字幕保持不同',state.player.secondary,'p:open:secondary')+pRange('字幕延迟','subtitleOffset',state.player.offset,-10,10,' 秒',.1)+pRange('字号','subtitleSize',PV.subtitleSize,14,40,' px')+pRange('距底部位置','subtitlePosition',PV.subtitlePosition,8,40,'%')+row('字体颜色','',state.subtitleColor,'p:open:subtitle-color')+(state.service==='Plex'?row('在线字幕搜索','当前服务支持','','p:open:subtitle-search','search'):notice('当前服务未开放在线字幕搜索，可导入本地字幕。'))+row('本地字幕','导入示例，不读取私人文件','','import-subtitle','plus');
if(t==='danmaku')body+=row(m.title,series?'第 '+state.season+' 季 · 第 '+state.episode+' 集':'电影 · 示例匹配','更换','p:open:danmaku-match')+toggle('显示弹幕','danmaku')+toggle('显示热力图','heatmap')+row('弹幕来源','仅使用用户配置网关',state.sources.length+' 个','p:open:sources')+row('手动搜索 / 本地导入','本地内容仅演示','','p:open:danmaku-match','search')+pRange('不透明度','danmakuOpacity',state.danmakuOpacity??70,10,100,'%')+pRange('字号','danmakuSize',state.danmakuSize??20,14,40,' px')+pRange('速度','danmakuSpeed',state.danmakuSpeed??50,10,100,'%')+pRange('同屏上限','sameScreen',PV.sameScreen,10,100,' 条')+pRange('显示区域','danmakuArea',state.danmakuArea??50,25,100,'%')+pRange('时间偏移','danmakuOffset',state.danmakuOffset??0,-20,20,' 秒',.1)+row('屏蔽词 / 过滤','','','p:open:danmaku-filter')+row('导入本地弹幕','示例 XML / JSON','','import-danmaku','plus');
body+=`<div class="p-panel-foot">${row('原型演示状态','轨道 / 权限 / 截图 / PiP / 切换失败','','p:open:player-demo')}${notice('浏览器演示，不改变真实播放、设备或服务。')}</div></div>`;return {title:'播放设置',body}}
if(name==='speed')return {title:'播放速度',body:[.5,.75,1,1.25,1.5,2].map(v=>pChoice(v+'×',v===1?'正常速度':'','choose:speed:'+v,state.player.speed===v,!pCanControl())).join('')};
if(name==='subtitle-menu')return {title:'字幕',body:(PV.trackCase==='empty'?notice('没有可用字幕轨道。可导入示例字幕。'):['简体中文 · ASS','繁體中文 · SRT','English · SRT','关闭'].map(v=>pChoice(v,'','choose:subtitle:'+v,state.player.subtitle===v)).join(''))+row('音轨','',state.player.audio,'p:open:audio')+(state.service==='Plex'?row('在线搜索','','','p:open:subtitle-search'):notice('当前服务不支持在线搜索'))+row('导入本地字幕','','','import-subtitle')+row('更多字幕设置','主副字幕 / 样式 / 延迟','','p:drawer:subtitles')};
if(name==='episode-menu'||name==='episodes'||name==='chapters'){let empty=PV.episodeCase==='empty';return {title:series?'选集与队列':'章节与队列',body:empty?notice(series?'此演示媒体没有可用剧集。':'此演示媒体没有章节信息。')+row('播放队列','','','p:open:queue'):series?`<label class="field">季<select data-p-select="season"><option value="1" ${state.season===1?'selected':''}>第 1 季</option><option value="2" ${state.season===2?'selected':''}>第 2 季</option></select></label>`+Array.from({length:6},(_,i)=>pChoice('第 '+(i+1)+' 集 · '+['出发之前','云深处','回声','见山','晚风','归来'][i],'45 分钟','p:episode:'+(i+1),state.episode===i+1,!pCanControl())).join('')+row('播放队列','','','p:open:queue'):['序章 · 靠近海岸','远方的信','晚风','回家'].map((n,i)=>pChoice(n,['00:00:00','00:25:36','01:04:00','01:48:48'][i],'p:chapter:'+[0,20,50,85][i],false,!pCanControl())).join('')+row('播放队列','','','p:open:queue')}};
if(name==='queue')return {title:'播放队列',body:media.slice(0,6).map(item=>pChoice(item.title,item.duration,'p:queue:'+item.id,item.id===state.media,!pCanControl())).join('')};
if(name==='audio')return {title:'音轨',body:PV.trackCase==='empty'?notice('没有可用音轨。当前示例保持静音状态。'):['普通话 · 立体声','English · 5.1','导演解说 · 立体声'].map(v=>pChoice(v,'','choose:audio:'+v,state.player.audio===v)).join('')};
if(name==='secondary'||name==='subtitle-language')return {title:name==='secondary'?'副字幕':'主字幕',body:PV.trackCase==='empty'?notice('没有可用字幕轨道。'):['关闭','简体中文 · ASS','繁體中文 · SRT','English · SRT'].map(v=>pChoice(v,name==='secondary'&&v!=='关闭'&&v===state.player.subtitle?'与主轨相同，请选择不同轨道':'','choose:'+(name==='secondary'?'secondary':'subtitle')+':'+v,state.player[name==='secondary'?'secondary':'subtitle']===v,name==='secondary'&&v!=='关闭'&&v===state.player.subtitle)).join('')};
if(name==='levels')return {title:'亮度与音量',body:pRange('亮度','brightness',state.player.brightness,0,100,'%')+pRange('音量','volume',state.player.volume,0,100,'%')+notice('只调整演示画面与数值，不改变系统亮度或音量。')};
if(name==='channel')return {title:'声道',body:['原始声道','立体声','单声道'].map(v=>pChoice(v,'','p:value:channel:'+v,PV.channel===v)).join('')};
if(name==='sleep')return {title:'睡眠定时',body:['关闭','15 分钟','30 分钟','本集结束'].map(v=>pChoice(v,'仅保存演示配置','p:value:sleep:'+v,PV.sleep===v)).join('')};
if(name==='screenshot')return {title:'截图预览 · 演示',body:PV.screenshotCase==='unsupported'?notice('当前演示平台不提供截图。真实应用仅在支持的 Android 路径提供此入口。'):PV.screenshotCase==='failure'?notice('未能生成截图，请重试。','error')+btn('重试演示','p:screenshot-retry','outline','refresh'):`<div class="p-capture-preview">${ART(m.art,true)}</div><p class="sheet-description">${m.title} · ${pTimeLabel(pTime())}<br>示例画面不包含弹幕和播放控件，不是对真实视频解码帧的截图。</p><div id="p-capture-result">${btn(PV.screenshotSaved?'已模拟保存':'模拟保存截图','p:screenshot-save','primary','check')}</div>`};
if(name==='pip-unavailable')return {title:'画中画不可用',body:notice('当前平台或浏览器能力不支持系统画中画。本原型不会调用系统 PiP。')+btn('查看可用演示','p:pip-enable','outline')};
if(name==='player-demo')return {title:'播放器演示状态',body:`<p class="sheet-description">只用于原型检查，不属于实际播放器设置。</p>${row('播放权限',pCanControl()?'可控制':'访客 / 仅房主','切换','p:demo:role')}${row('轨道数据',PV.trackCase==='empty'?'无轨道':'有字幕与音轨','切换','p:demo:tracks')}${row('章节 / 剧集',PV.episodeCase==='empty'?'空列表':'可用列表','切换','p:demo:episodes')}${row('选择结果',PV.switchOutcome==='success'?'成功':'失败（保留旧值）','切换','p:demo:switch')}<h3 style="margin:20px 0 10px">截图能力</h3><div class="chips">${['available','failure','unsupported'].map((v,i)=>`<button class="chip ${PV.screenshotCase===v?'active':''}" data-action="p:demo:screenshot:${v}">${['可用演示','失败','不支持'][i]}</button>`).join('')}</div><h3 style="margin:20px 0 10px">画中画能力</h3><div class="chips">${['available','unsupported'].map((v,i)=>`<button class="chip ${PV.pipCase===v?'active':''}" data-action="p:demo:pip:${v}">${['可用演示','不支持'][i]}</button>`).join('')}</div>${notice('加载 / 结束 / 失败使用顶部全局演示状态。实际设备能力未经本原型验证。')}`};
return modalContent(name)}
function pRenderLayer(){if(!state.modal)return;let data=pLayerData(state.modal),back=PV.stack.length>0;$('#modal-root').innerHTML=`<div class="modal-backdrop p-backdrop ${PV.kind==='popover'?'p-popover-backdrop':''}"><section class="sheet p-layer-panel ${PV.kind==='popover'?'p-popover':'p-floating-drawer'}" role="dialog" aria-modal="true" aria-label="${esc(data.title)}"><div class="p-layer-head">${back?pButton('返回上层','close','back'):''}<h2>${data.title}</h2><span class="spacer"></span>${pButton('关闭当前面板','close','close')}</div><div class="p-layer-scroll">${data.body}</div><div class="p-selection-status" id="p-selection-status" role="status"></div></section></div>`;pPositionLayer();requestAnimationFrame(()=>{let selected=$('.p-layer-panel .choice.selected:not(:disabled)');(selected||$('.p-layer-panel button:not(:disabled),.p-layer-panel input,.p-layer-panel select'))?.focus();if(state.modal==='player-settings'&&$('.p-layer-scroll'))$('.p-layer-scroll').scrollTop=PV.tabScroll[state.player.tab]||0})}
function pPositionLayer(){let panel=$('.p-layer-panel'),stage=$('#player-stage');if(!panel||!stage)return;let r=stage.getBoundingClientRect(),pad=12;if(PV.kind==='popover'){let bottom=$('.p-bottom')?.getBoundingClientRect().top||r.bottom-90,topLimit=($('.p-top')?.getBoundingClientRect().bottom||r.top+54)+8,avail=Math.max(68,bottom-topLimit-PC.popoverGap),width=Math.min(PC.popoverWidth,r.width-pad*2),a=PV.anchor?.isConnected?PV.anchor.getBoundingClientRect():{left:r.right-width,width:width};panel.style.width=width+'px';panel.style.maxHeight=Math.min(avail,420)+'px';panel.style.left=pClamp(a.left+a.width/2-width/2,r.left+pad,r.right-pad-width)+'px';panel.style.bottom=Math.max(0,window.innerHeight-bottom+PC.popoverGap)+'px';panel.style.top='auto'}else{panel.style.width=Math.min(state.view==='tv'?460:370,r.width-pad*2)+'px';panel.style.height=Math.max(120,r.height-pad*2)+'px';panel.style.maxHeight=Math.max(120,r.height-pad*2)+'px';panel.style.right=Math.max(pad,window.innerWidth-r.right+pad)+'px';panel.style.top=Math.max(pad,r.top+pad)+'px'}}
function pFinishChoice(key,value){if(key==='speed'&&!pCanControl())return;if(key==='secondary'&&value!=='关闭'&&value===state.player.subtitle)return;pCancelGesture();if(key==='speed')state.player.speed=Number(value);else state.player[key]=value;if(key==='subtitle'){state.settings.subtitle=value!=='关闭';if(value!=='关闭'&&state.player.secondary===value)state.player.secondary='关闭'}if(key==='secondary'&&value!=='关闭')state.settings.subtitle=true;closeModal();render();pFeedback('已选择 '+value+' · 演示','center','check')}
function pChoose(key,value,{retry=false}={}){if(state.player.locked)return;if(key==='secondary'&&value!=='关闭'&&value===state.player.subtitle){let target=$('#p-selection-status');if(target)target.innerHTML=notice('副字幕不能与主字幕使用相同轨道，请选择另一条。');return}if(key==='speed'&&!pCanControl())return pFeedback('仅房主可调整速度','center','lock');const token=++PV.selectionToken;PV.pendingChoice={key,value};let target=$('#p-selection-status');if(target)target.innerHTML='<span class="spinner"></span> 正在应用 · 演示';$$('.p-layer-panel .choice').forEach(el=>el.disabled=true);setTimeout(()=>{if(token!==PV.selectionToken||state.route!=='player'||!state.modal)return;if(PV.switchOutcome==='failure'&&!retry){if(target?.isConnected)target.innerHTML=notice('切换失败，保留原来的设置。','error')+btn('重试此选择','p:retry-choice','outline small','refresh');$$('.p-layer-panel .choice').forEach(el=>el.disabled=false);return}pFinishChoice(key,value)},PC.switchMs)}
function pTogglePlay(){if(!pCanControl()||state.player.locked)return pFeedback('仅房主可控制播放','center','lock');if(state.scenario==='empty'){state.player.time=0;state.scenario='normal'}state.player.playing=!state.player.playing;state.player.hud=true;render();pFeedback(state.player.playing?'继续播放':'已暂停','center',state.player.playing?'play':'pause');scheduleHud()}
function pRefreshLayer(){let focus=captureFocus(),scroll=$('.p-layer-scroll')?.scrollTop||0;render();pRenderLayer();requestAnimationFrame(()=>{restoreFocus(focus);if($('.p-layer-scroll'))$('.p-layer-scroll').scrollTop=scroll})}
function pAct(action,el){let parts=action.split(':'),verb=parts[1],v=parts.slice(2).join(':');if(verb==='play'){pTogglePlay();return}if(verb==='skip-intro'){if(!pCanControl()||state.player.locked)return;pCommitSeek(PC.durationSeconds*PC.introEndPercent/100);pFeedback('已跳过片头 · 演示','center','skip');return}if(verb==='recover'){if(!pCanControl()||state.player.locked){pFeedback('仅房主可恢复或重播','center','lock');return}if(state.scenario==='empty')state.player.time=0;state.scenario='normal';state.player.playing=true;state.player.hud=true;render();scheduleHud();return}if(verb==='danmaku'){state.settings.danmaku=!state.settings.danmaku;render();pFeedback(state.settings.danmaku?'弹幕已开启':'弹幕已关闭','center','subtitle');return}if(verb==='lock'){pCancelGesture();if(state.modal){PV.stack=[];closeModal(false)}state.player.locked=!state.player.locked;state.player.hud=!state.player.locked;render();$('[data-action="p:lock"]')?.focus();return}if(verb==='orientation'){pCancelGesture();PV.orientation=PV.orientation==='landscape'?'portrait':'landscape';render();pFeedback((PV.orientation==='landscape'?'横屏':'竖屏')+'布局演示，不改变设备方向','center','rotate');return}if(verb==='popover'){if((v==='speed'||v==='episode-menu')&&!pCanControl())return pFeedback('仅房主可控制','center','lock');pOpen(v,'popover',el,{root:true});return}if(verb==='drawer'){state.player.tab=v||'video';pOpen('player-settings','drawer',el,{root:true});return}if(verb==='tab'){PV.tabScroll[state.player.tab]=$('.p-layer-scroll')?.scrollTop||0;state.player.tab=v;pRenderLayer();return}if(verb==='open'){pOpen(v,'drawer',el);return}if(verb==='value'){let key=parts[2],value=parts.slice(3).join(':');PV[key]=value;closeModal();render();return}if(verb==='reset-audio'){PV.audioDelay=PC.defaultAudioDelay;PV.gain=PC.defaultGain;PV.channel=PC.defaultChannel;pRefreshLayer();return}
if(verb==='episode'||verb==='queue'||verb==='chapter'||verb==='next'){if(!pCanControl())return pFeedback('仅房主可切换内容','center','lock');pCancelGesture();if(verb==='episode')state.episode=Number(v);if(verb==='queue')state.media=Number(v);if(verb==='next'){if(selectedMedia().duration.includes('集'))state.episode=state.episode>=6?1:state.episode+1;else state.media=(state.media+1)%media.length}if(verb==='chapter')state.player.time=Number(v);else state.player.time=0;state.scenario='normal';state.player.playing=true;if(state.modal){PV.stack=[];closeModal()}render();pFeedback(verb==='chapter'?'已跳转章节':selectedMedia().duration.includes('集')?'第 '+state.episode+' 集':'已切换 '+selectedMedia().title,'center','play');scheduleHud();return}
if(verb==='screenshot'){PV.screenshotSaved=false;pOpen('screenshot','drawer',el,{root:true});return}if(verb==='screenshot-retry'){PV.screenshotCase='available';pRenderLayer();return}if(verb==='screenshot-save'){PV.screenshotSaved=true;$('#p-capture-result').innerHTML=notice('已模拟保存此帧。没有写入系统相册或生成真实视频截图。');return}if(verb==='pip'){if(PV.pipCase==='unsupported'){pOpen('pip-unavailable','drawer',el,{root:true});return}PV.pip=!PV.pip;render();pFeedback(PV.pip?'已打开画中画演示窗':'已回到主画面','center','pip');return}if(verb==='pip-enable'){PV.pipCase='available';PV.stack=[];closeModal();PV.pip=true;render();return}if(verb==='pip-close'){PV.pip=false;render();$('[data-action="p:pip"]')?.focus();return}if(verb==='request'){pFeedback('播放控制请求已发送给房主 · 演示','center','users');return}if(verb==='retry-choice'){if(PV.pendingChoice)pChoose(PV.pendingChoice.key,PV.pendingChoice.value,{retry:true});return}
if(verb==='demo'){let key=parts[2],value=parts[3];if(key==='role'){if(pCanControl()){state.room.joined=true;state.room.role='guest';state.room.control='hostOnly'}else{state.room.role='host';state.room.joined=true}}if(key==='tracks')PV.trackCase=PV.trackCase==='available'?'empty':'available';if(key==='episodes')PV.episodeCase=PV.episodeCase==='available'?'empty':'available';if(key==='switch')PV.switchOutcome=PV.switchOutcome==='success'?'failure':'success';if(key==='screenshot')PV.screenshotCase=value;if(key==='pip')PV.pipCase=value;pRefreshLayer();return}
}
doAction=function(action,el){if(state.route!=='player')return playerLegacy.doAction(action,el);if(el?.closest('#prototype-bar')){pCancelGesture();return playerLegacy.doAction(action,el)}if(state.player.locked&&action!=='p:lock'&&action!=='close')return;if(action.startsWith('p:'))return pAct(action,el);if(action.startsWith('choose:')){let bits=action.split(':');return pChoose(bits[1],bits.slice(2).join(':'))}if(action.startsWith('modal:'))return pOpen(action.slice(6),'drawer',el);if(action.startsWith('player-tab:')){state.player.tab=action.split(':')[1];return pOpen('player-settings','drawer',el,{root:true})}if(action==='play-toggle')return pTogglePlay();if(action.startsWith('seek:'))return pSeek(Number(action.slice(5)));if(action==='lock')return pAct('p:lock',el);if(action==='skip-intro'){pCommitSeek(PC.durationSeconds*PC.introEndPercent/100);return}if(action==='import-subtitle'){PV.trackCase='available';state.player.subtitle='本地示例 · SRT';state.settings.subtitle=true;closeModal();render();pFeedback('已导入本地示例字幕 · 演示','center','subtitle');return}if(action==='import-danmaku'){state.settings.danmaku=true;closeModal();render();pFeedback('已导入本地示例弹幕 · 演示','center','chart');return}if(action.startsWith('subtitle-color:')){state.subtitleColor=action.slice(15);closeModal();render();return}if(action==='go:settings/subtitles')return pOpen('player-settings','drawer',el);return playerLegacy.doAction(action,el)};
render=function(){if(state.route==='player'&&state.scenario!=='normal')state.player.hud=true;const result=playerLegacy.render();if(state.route==='player'){$$('.p-hud').forEach(n=>n.inert=state.player.locked||!state.player.hud);let left=$('.p-left-edge');if(left)left.inert=!state.player.hud&&!state.player.locked;pPositionLayer();scheduleHud()}return result};
function pIsInteractive(target){return !!target.closest('button,input,select,textarea,a,[role="slider"],.p-layer-panel,.p-pip-window')}
function pTap(x){if(state.player.locked)return;if(state.modal)return;let r=$('#player-stage')?.getBoundingClientRect();if(!r)return;let zone=pClamp((x-r.left)/r.width,0,1);if(zone<1/3)pSeek(-PC.seekStepSeconds);else if(zone>2/3)pSeek(PC.seekStepSeconds);else pTogglePlay();PV.lastDouble=Date.now()}
function pScheduleTap(x,y){const now=Date.now(),last=PV.lastTap;if(last&&now-last.at<=PC.doubleTapMs&&Math.hypot(x-last.x,y-last.y)<PC.doubleTapDistance){clearTimeout(PV.tapTimer);PV.lastTap=null;pTap(x);return}PV.lastTap={x,y,at:now};clearTimeout(PV.tapTimer);PV.tapTimer=setTimeout(()=>{PV.lastTap=null;pSetHud(!state.player.hud)},PC.doubleTapMs)}
function pPositionSeconds(x){let r=$('#p-timeline').getBoundingClientRect();return pClamp((x-r.left)/r.width,0,1)*PC.durationSeconds}
document.addEventListener('pointerdown',e=>{if(state.route!=='player'||!e.target.closest('#player-stage')||state.modal)return;if(PV.gesture){if(e.pointerId!==PV.gesture.id){clearTimeout(PV.gesture.timer);PV.gesture.multi=true;if(PV.temporaryBase!==null){state.player.speed=PV.temporaryBase;PV.temporaryBase=null;pSync()}}return}if(e.button!==0&&e.pointerType==='mouse')return;PV.inputMode=e.pointerType==='mouse'?'mouse':'touch';if(state.player.locked){if(!e.target.closest('button')){e.preventDefault();e.stopImmediatePropagation()}return}const timeline=e.target.closest('#p-timeline');if(!timeline&&pIsInteractive(e.target))return;e.preventDefault();e.stopImmediatePropagation();clearTimeout(PV.hideTimer);let stage=$('#player-stage'),r=stage.getBoundingClientRect(),g={id:e.pointerId,type:timeline?'timeline':'screen',target:timeline||stage,x:e.clientX,y:e.clientY,startSeconds:pTime(),rect:r,intent:'',channel:e.clientX<r.left+r.width/2?'brightness':'volume',multi:false};g.initialLevel=state.player[g.channel];PV.gesture=g;try{g.target.setPointerCapture(e.pointerId)}catch{}if(timeline){if(!pCanControl()){PV.gesture=null;pFeedback('仅房主可调整进度','center','lock');return}pPreview(pPositionSeconds(e.clientX),'长按查看热度，拖动精准定位');g.timer=setTimeout(()=>{if(PV.gesture!==g||g.intent||g.multi)return;g.intent='heat-preview';pPreview(pPositionSeconds(e.clientX),'热力预览 · 松手不跳转')},PC.heatLongPressMs)}else{g.timer=setTimeout(()=>{if(PV.gesture!==g||g.intent||g.multi||!pCanControl()||state.player.locked)return;g.intent='long-speed';PV.temporaryBase=state.player.speed;state.player.speed=PC.temporarySpeed;pSync();pFeedback(PC.temporarySpeed+'× 临时倍速 · 松手恢复','center','forward',true)},PC.longPressMs)}},true);
document.addEventListener('pointermove',e=>{if(state.route!=='player')return;let g=PV.gesture;if(g&&e.pointerId===g.id){e.preventDefault();e.stopImmediatePropagation();if(g.multi)return;let dx=e.clientX-g.x,dy=e.clientY-g.y;if(!g.intent&&Math.hypot(dx,dy)>PC.gestureThreshold){clearTimeout(g.timer);if(g.type==='timeline')g.intent='timeline-drag';else g.intent=Math.abs(dx)>Math.abs(dy)?'seek':'vertical'}if(g.intent==='long-speed'||g.intent==='heat-preview')return;if(g.intent==='timeline-drag'){pPreview(pPositionSeconds(e.clientX),'精准拖动 · 松手定位');pSync()}if(g.intent==='seek'){if(!pCanControl()){pFeedback('仅房主可调整进度','center','lock');return}pPreview(g.startSeconds+dx/g.rect.width*PC.durationSeconds*PC.seekDragFraction,'横向拖动 · 松手定位');pSync()}if(g.intent==='vertical'){state.player[g.channel]=Math.round(pClamp(g.initialLevel-dy/g.rect.height*100*PC.verticalGain));pSync();pFeedbackLevel(g.channel,state.player[g.channel])}return}if(state.modal||state.player.locked)return;let timeline=e.target.closest('#p-timeline');if(timeline&&e.pointerType!=='touch'){pPreview(pPositionSeconds(e.clientX),'热力预览 · 点击热点可辅助定位');e.stopImmediatePropagation();clearTimeout(PV.hideTimer)}},true);
document.addEventListener('pointerup',e=>{if(state.route!=='player')return;let g=PV.gesture;if(!g||e.pointerId!==g.id)return;e.preventDefault();e.stopImmediatePropagation();clearTimeout(g.timer);PV.gesture=null;PV.lastPointerUp=Date.now();try{g.target.releasePointerCapture(e.pointerId)}catch{}if(g.multi){pCancelGesture();return}if(g.intent==='long-speed'){state.player.speed=PV.temporaryBase??state.player.speed;PV.temporaryBase=null;pSync();pFeedback('恢复 '+state.player.speed+'×','center','check')}else if(g.intent==='timeline-drag'||g.intent==='seek'){let value=PV.preview??g.startSeconds;pCommitSeek(value);pClearPreview()}else if(g.intent==='vertical'){pHideLevel()}else if(g.intent==='heat-preview'){pClearPreview()}else if(g.type==='timeline'){pCommitSeek(pPositionSeconds(e.clientX),{assist:true});pClearPreview()}else pScheduleTap(e.clientX,e.clientY);scheduleHud()},true);
document.addEventListener('pointercancel',e=>{if(state.route!=='player'||!PV.gesture||e.pointerId!==PV.gesture.id)return;e.stopImmediatePropagation();pCancelGesture();pFeedback('操作已取消，设置已恢复','center','check');scheduleHud()},true);
document.addEventListener('lostpointercapture',e=>{if(state.route==='player'&&PV.gesture?.id===e.pointerId){pCancelGesture();scheduleHud()}},true);
document.addEventListener('pointerout',e=>{if(state.route==='player'&&!PV.gesture&&e.target.closest?.('#p-timeline')&&!e.relatedTarget?.closest?.('#p-timeline')){pClearPreview();scheduleHud()}},true);
document.addEventListener('click',e=>{if(state.route!=='player'||!e.target.closest('#player-stage,#modal-root'))return;let el=e.target.closest('[data-action]');if(el){e.preventDefault();e.stopImmediatePropagation();if(!el.disabled)doAction(el.dataset.action,el);return}if(e.target.classList.contains('p-backdrop')){e.stopImmediatePropagation();closeModal();return}if(e.target.closest('.p-layer-panel'))return;e.stopImmediatePropagation();if(!pIsInteractive(e.target)&&!state.player.locked&&!state.modal&&Date.now()-(PV.lastPointerUp||0)>400)pScheduleTap(e.clientX,e.clientY)},true);
document.addEventListener('dblclick',e=>{if(state.route!=='player'||!e.target.closest('#player-stage'))return;e.preventDefault();e.stopImmediatePropagation();if(pIsInteractive(e.target)||state.modal||state.player.locked)return;clearTimeout(PV.tapTimer);PV.lastTap=null;if(Date.now()-PV.lastDouble>PC.doubleTapMs)pTap(e.clientX)},true);
document.addEventListener('input',e=>{if(state.route!=='player')return;let el=e.target,key=el.dataset.pRange;if(!key)return;e.stopImmediatePropagation();if(state.player.locked)return;let value=Number(el.value);let output=$('#p-out-'+key);if(output)output.textContent=value+(el.dataset.unit||'');if(key==='brightness'||key==='volume')state.player[key]=value;else if(key==='subtitleOffset')state.player.offset=value;else if(key.startsWith('danmaku'))state[key]=value;else PV[key]=value;let focus=captureFocus();playerLegacy.render();restoreFocus(focus);pSync();pPositionLayer()},true);
document.addEventListener('change',e=>{if(state.route!=='player'||e.target.dataset.pSelect!=='season')return;e.stopImmediatePropagation();if(!pCanControl()||state.player.locked)return;state.season=Number(e.target.value);state.episode=1;pRefreshLayer()},true);
function pFocusables(root){return Array.from(root?.querySelectorAll('button:not(:disabled),a,input:not(:disabled),select:not(:disabled),textarea,[tabindex="0"]')||[]).filter(x=>x.offsetParent!==null&&!x.closest('[inert]')&&!x.disabled)}
function pMoveFocus(key){let root=state.modal?$('.p-layer-panel'):$('#player-stage'),items=pFocusables(root),cur=document.activeElement;if(!items.length)return;if(!items.includes(cur)){items[0].focus();return}let r=cur.getBoundingClientRect(),cx=r.x+r.width/2,cy=r.y+r.height/2,dx=key==='ArrowRight'?1:key==='ArrowLeft'?-1:0,dy=key==='ArrowDown'?1:key==='ArrowUp'?-1:0;let next=items.filter(x=>x!==cur).map(x=>{let q=x.getBoundingClientRect(),xx=q.x+q.width/2-cx,yy=q.y+q.height/2-cy;return{x,xx,yy,score:Math.abs(dx?xx:yy)+Math.abs(dx?yy:xx)*2}}).filter(o=>dx?o.xx*dx>8:o.yy*dy>8).sort((a,b)=>a.score-b.score)[0];if(next){next.x.focus();next.x.scrollIntoView({block:'nearest',inline:'nearest',behavior:'auto'})}}
document.addEventListener('keydown',e=>{if(state.route!=='player')return;const target=document.activeElement,typing=['INPUT','TEXTAREA','SELECT'].includes(target?.tagName);if(e.key==='Escape'){e.preventDefault();e.stopImmediatePropagation();if(state.player.locked){pAct('p:lock');return}if(state.modal)closeModal();else back();return}if(state.player.locked){if(e.key==='Tab'||e.key.startsWith('Arrow')){e.preventDefault();e.stopImmediatePropagation();$('[data-action="p:lock"]')?.focus()}else if(e.code==='Space'||e.key==='Enter'){e.preventDefault();e.stopImmediatePropagation();if(target?.dataset.action==='p:lock')pAct('p:lock')}return}if(e.key==='Tab'&&state.modal){e.stopImmediatePropagation();let items=pFocusables($('.p-layer-panel')),first=items[0],last=items.at(-1);if(e.shiftKey&&target===first){e.preventDefault();last?.focus()}else if(!e.shiftKey&&target===last){e.preventDefault();first?.focus()}return}if(typing)return;PV.inputMode=state.view==='tv'?'touch':PV.inputMode;if(e.key.startsWith('Arrow')||e.code==='Space'||e.key==='Enter')showHud();if(target?.id==='p-timeline'){if(['ArrowLeft','ArrowRight','Home','End','Enter'].includes(e.key)){e.preventDefault();e.stopImmediatePropagation();if(!pCanControl())return;pCommitSeek(e.key==='Home'?0:e.key==='End'?PC.durationSeconds:e.key==='Enter'?(state.settings.heatmap?pNearestPeak(pTime()):pTime()):pTime()+(e.key==='ArrowLeft'?-PC.timelineKeyStepSeconds:PC.timelineKeyStepSeconds));return}}if(state.view==='tv'&&e.key.startsWith('Arrow')){e.preventDefault();e.stopImmediatePropagation();pMoveFocus(e.key);return}if(state.modal)return;if(e.code==='Space'&&!target?.closest('button')){e.preventDefault();e.stopImmediatePropagation();pTogglePlay();return}if(state.view!=='tv'&&['ArrowLeft','ArrowRight'].includes(e.key)&&!target?.closest('button')){e.preventDefault();e.stopImmediatePropagation();pSeek(e.key==='ArrowLeft'?-PC.seekStepSeconds:PC.seekStepSeconds);return}},true);
window.addEventListener('resize',()=>{if(state.route==='player'){pCancelGesture();document.documentElement.style.setProperty('--prototypebar-height',($('#prototype-bar')?.offsetHeight||42)+'px');pPositionLayer()}});
document.addEventListener('visibilitychange',()=>{if(document.hidden&&state.route==='player')pCancelGesture()});
window.addEventListener('hashchange',()=>{if(state.route!=='player')pDispose()});
render();
